import{_ as e,o,c as r,ag as n}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学新闻核实","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/science-news/index.md","filePath":"topics/science-news/index.md"}'),a={name:"topics/science-news/index.md"};function s(i,t,l,d,u,c){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="科学新闻核实" tabindex="-1">科学新闻核实 <a class="header-anchor" href="#科学新闻核实" aria-label="Permalink to &quot;科学新闻核实&quot;">​</a></h1><p>用户转来的科学新闻 / 自媒体科普摘要的<strong>信源核实记录</strong>。</p><h2 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="/zhishiku-reading/topics/science-news/news-verification-2026-10-23.html">news-verification-2026-10-23.md</a></td><td>2026-10-23 那条五段式「科学日报」18 条<strong>逐条核实</strong>：一页速查表（真实出处 + DOI）、三条类失真归类、AI 段 4 条 36kr 标题党打假、<strong>两处自我更正记录</strong></td></tr></tbody></table><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Google News RSS 定位原始报道 → 抓原文正文 → <strong>CrossRef API 核 DOI</strong> → PubMed E-utilities 核论文。 逐条给四段：① 真实来源（期刊/机构 + 日期 + 标题原文）② 具体研究内容（谁做、方法、关键数字、DOI）③ 中文转述 vs 真实的差异/夸大 ④ 核实级别。</p><h2 id="三类失真-可复用的检查清单" tabindex="-1">三类失真（可复用的检查清单） <a class="header-anchor" href="#三类失真-可复用的检查清单" aria-label="Permalink to &quot;三类失真（可复用的检查清单）&quot;">​</a></h2><ol><li><strong>时间错位</strong> —— 旧报道（数月前）被当作&quot;今日新闻&quot;重发。ScienceDaily 会把 6 月的新闻稿在 10 月<strong>再推送</strong>一次，中文&quot;日报&quot;照抄。</li><li><strong>程度夸大</strong> —— 理论预测 / 模型输出 / 设计蓝图 → &quot;已实现 / 突破 / 首个&quot;。凡&quot;降低 100 倍&quot;&quot;效率提升 40 倍&quot;都要问：是<strong>实测</strong>还是<strong>算出来的</strong>？</li><li><strong>主体 / 口径 / 方向错位</strong> —— 仪器张冠李戴（相机锐度说成日冕仪）、基因名错（GFAP 写成 FOXD1）、把 GDP <strong>总量</strong>说成<strong>增量</strong>、<strong>把 &quot;reversal（向下逆转）&quot; 读成 &quot;反弹（向上）&quot;</strong>。</li></ol><h2 id="铁律" tabindex="-1">铁律 <a class="header-anchor" href="#铁律" aria-label="Permalink to &quot;铁律&quot;">​</a></h2><ul><li><strong>凡&quot;突破 / 首个 / 破解 / 再创新低&quot;字样，先查发布日期 + 原文措辞</strong>，再信中文。</li><li><strong>ScienceDaily 标题本身就是第一层失真源</strong>（never-ending / reversed / this one age / stunning reversal）—— 中文直译会再放大一层。</li><li>核实到&quot;未经同行评议 / 不可复现 / 器件未造 / 仅立项&quot;这类限定，<strong>必须写进结论</strong>，它们往往正是&quot;争议&quot;的真实内容。</li><li><strong>不编造</strong>：&quot;我查不到&quot;是合法状态；子代理的自报结论也须亲验后再落盘。</li></ul><hr><blockquote><p>关键词：科学新闻核实、信源核实、36kr 标题党、时间错位、程度夸大、主体错位、方向读反、DOI 核实、CrossRef、ScienceDaily 标题党、黎曼猜想、TheoPhysEval、GPT-6 Astra、Zanvastro、GFAP、Alexander 病、GIMLI、钍-229 核时钟、BVR-19、SHOQ、DT-109</p></blockquote>',12)])])}const q=e(a,[["render",s]]);export{h as __pageData,q as default};
